const startMinutes=startHour*60+startMinute;const endMinutes=endHourAdjusted*60+endMinute;const durationMinutes=endMinutes-startMinutes;const height=(durationMinutes/30)*getIntervalHeight();const top=startSlot.offsetTop;const card=document.createElement("div");card.className="reservation-card";if(reservation.status==="pending"){card.classList.add("status-pending");}
