function initQuickDurationButtons(){document.querySelectorAll(".duration-btn").forEach((button)=>{button.onclick=function(){const hours=parseFloat(this.dataset.hours||this.textContent);if(!window.startTimePicker||!window.endTimePicker)return;let startDate=window.startTimePicker.selectedDates[0];if(!startDate){const startInput=document.getElementById("start_time");if(startInput?.value){const[rawHour,rawMinute]=startInput.value.split(":").map((val)=>parseInt(val,10));if(!isNaN(rawHour)){const base=new Date();base.setHours(0,0,0,0);const hour=rawHour>=24?rawHour-24:rawHour;base.setHours(hour,rawMinute||0,0,0);if(rawHour>=24){base.setDate(base.getDate()+1);}
startDate=base;window.startTimePicker.setDate(startDate,false);}}}
if(!startDate)return;const endDate=new Date(startDate);endDate.setMinutes(startDate.getMinutes()+hours*60);window.endTimePicker.setDate(endDate);updatePriceEstimate();document.querySelectorAll(".duration-btn").forEach((btn)=>btn.classList.remove("active"));this.classList.add("active");};});}
function updatePriceEstimate(){const startTimeInput=document.getElementById("start_time");const endTimeInput=document.getElementById("end_time");if(!startTimeInput||!endTimeInput){console.error("Time inputs not found");return;}
if(!window.startTimePicker||!window.endTimePicker)return;const sDate=window.startTimePicker.selectedDates[0];const eDate=window.endTimePicker.selectedDates[0];if(!sDate||!eDate)return;let startHour=sDate.getHours();const startMinutes=sDate.getMinutes();let endHour=eDate.getHours();const endMinutes=eDate.getMinutes();if(endHour<startHour)endHour+=24;const startTimeInMinutes=startHour*60+startMinutes;const endTimeInMinutes=endHour*60+endMinutes;const durationInMinutes=endTimeInMinutes-startTimeInMinutes;const durationInHours=durationInMinutes/60;let earlyBirdHours=0;let eveningHours=0;for(let time=startTimeInMinutes;time<endTimeInMinutes;time+=30){let currentHour=Math.floor(time/60);if(currentHour>=24)currentHour-=24;if(currentHour>=11&&currentHour<18){earlyBirdHours+=0.5;}else if(currentHour>=18||currentHour<1){eveningHours+=0.5;}}
const earlyBirdCharge=earlyBirdHours*35;const eveningCharge=eveningHours*50;const totalCharge=earlyBirdCharge+eveningCharge;const periodCharges=[];if(earlyBirdHours>0){periodCharges.push({label:"Early Bird Rate (11am-6pm)",rate:35,duration:earlyBirdHours,amount:earlyBirdCharge,});}
if(eveningHours>0){periodCharges.push({label:"Evening Rate (6pm-1am)",rate:50,duration:eveningHours,amount:eveningCharge,});}
const taxRate=0.055;const taxAmount=totalCharge*taxRate;const totalWithTax=totalCharge+taxAmount;try{const roomRateElement=document.getElementById("room-rate");if(roomRateElement){roomRateElement.textContent=`$${totalCharge.toFixed(2)}`;}
const taxElement=document.getElementById("tax-amount");if(taxElement){taxElement.textContent=`$${taxAmount.toFixed(2)}`;}
const totalElement=document.getElementById("total-cost");if(totalElement){totalElement.textContent=`$${totalWithTax.toFixed(2)}`;}
const periodChargesContainer=document.getElementById("period-charges");if(periodChargesContainer&&periodCharges.length>0){periodChargesContainer.replaceChildren();periodCharges.forEach((charge)=>{const periodCharge=document.createElement("div");periodCharge.className="period-charge";const row=document.createElement("div");row.className="period-charge-row";const label=document.createElement("div");label.className="period-label";label.textContent=charge.label;const amount=document.createElement("div");amount.className="period-amount";amount.textContent=`$${charge.amount.toFixed(2)}`;row.append(label,amount);const details=document.createElement("div");details.className="period-details";details.textContent=`$${charge.rate}/hr x ${charge.duration} ${
          charge.duration === 1 ? "hour" : "hours"
        }`;periodCharge.append(row,details);periodChargesContainer.appendChild(periodCharge);});}else{periodChargesContainer.replaceChildren();const noCharges=document.createElement("div");noCharges.className="no-charges";noCharges.textContent="No charges calculated";periodChargesContainer.appendChild(noCharges);}
console.log("Price calculation:",{startTime:`${startHour}:${startMinutes}`,endTime:`${endHour}:${endMinutes}`,durationInHours,earlyBirdHours,eveningHours,earlyBirdCharge,eveningCharge,totalCharge,taxAmount,totalWithTax,});}catch(error){console.error("Error updating price display:",error);console.error("Error details:",error.stack);}}
