if(window.endTimePicker){window.endTimePicker.destroy();window.endTimePicker=null;}
let defaultStartHour=11;let defaultStartMinute=0;if(startTimeStr){const[h,m]=startTimeStr.split(":").map(Number);defaultStartHour=h;defaultStartMinute=m;}else if(initialHour!==null){defaultStartHour=initialHour;defaultStartMinute=initialMinute||0;}
